import json, random, subprocess, sys, os, tempfile
sys.path.insert(0,'/workspace/tmp')
from ref import Ref
MAIN='/workspace/submission/main.py'
def run(prog,reqs):
    with tempfile.TemporaryDirectory() as d:
        p=os.path.join(d,'p.json'); open(p,'w').write(json.dumps(prog))
        pr=subprocess.Popen([sys.executable,'-I',MAIN,'stream',p],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
        out,err=pr.communicate('\n'.join(json.dumps(r) for r in reqs)+'\n')
        return out,err,pr.returncode
def comp(cfg):
    return subprocess.run([sys.executable,'-I',MAIN,'compile'],input=json.dumps(cfg),stdout=subprocess.PIPE,text=True)
rng=random.Random(777)
for it in range(120):
    W=rng.randint(1,32)
    rules=[]; used=set(); total=0
    for _ in range(rng.randint(0,8)):
        rid=rng.randint(0,60)
        while rid in used: rid=rng.randint(0,80)
        used.add(rid); k=rng.randint(1,32)
        if total+k>16384: break
        total+=k
        rg=[]
        for _ in range(k):
            lo=rng.randint(-4,4); hi=rng.randint(lo,4); rg.append([lo,hi])
        rules.append({"id":rid,"class":rng.randint(0,2),"priority":rng.randint(-3,3),"ranges":rg})
    def leaf(): return {"class":rng.randint(0,2)}
    def tree(d):
        if d>=5 or rng.random()<0.4: return leaf()
        return {"feature":rng.randint(0,W-1),"threshold":rng.randint(-3,3),"le":tree(d+1),"gt":tree(d+1)}
    cfg={"version":1,"idle_timeout":rng.choice([0,1,2,5]),"packet_limit":rng.randint(1,40),"prefix_width":W,"rules":rules,"fallback":tree(0)}
    cp=comp(cfg); assert cp.returncode==0,(cp.stdout,cfg)
    prog=json.loads(cp.stdout)
    reqs=[]; opf=[]; t=0
    for _ in range(30):
        c=rng.choice(['open','chunk','tick','close'])
        if c=='open' and len(opf)<4:
            t+=rng.randint(0,2); f=rng.randint(0,6)
            if f not in opf: reqs.append({"op":"open","flow":f,"time":t}); opf.append(f); continue
        if c=='chunk':
            pk=[]
            for _ in range(rng.randint(0,5)):
                if not opf: break
                t+=rng.randint(0,2); pk.append({"flow":rng.choice(opf),"time":t,"source":rng.randint(0,1),"length":rng.randint(1,6)})
            reqs.append({"op":"chunk","packets":pk})
        elif c=='close' and opf:
            t+=rng.randint(0,2); f=rng.choice(opf); reqs.append({"op":"close","flow":f,"time":t}); opf.remove(f)
        else:
            t+=rng.randint(0,3); reqs.append({"op":"tick","time":t})
    for f in list(opf):
        t+=rng.randint(0,2); reqs.append({"op":"close","flow":f,"time":t})
    out,err,rc=run(prog,reqs); assert rc==0,err
    got=[json.loads(x) for x in out.strip().split('\n') if x.strip()]
    r=Ref(cfg); exp=[]
    ok=True
    for q in reqs:
        try: exp.append(r.handle(q))
        except ValueError: exp.append({"error":"event"}); ok=False; break
    if got!=exp:
        print("MISMATCH Wtest",it); print(json.dumps(cfg)); print(json.dumps(reqs))
        for i,(g,e) in enumerate(zip(got,exp)):
            if g!=e: print(i,json.dumps(g),json.dumps(e)); break
        break
else:
    print("W-large ALL OK 120")
